///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name PopupAutoResizeBy
 * @description Popup Auto Resize By 처리
 * @returns {void}
 * @hidden N
 */
scwin.PopupAutoResizeBy = function () {

    let mw = 0;
    let mh = 0;
    if (innerWidth && innerHeight) {
        mw = outerWidth - innerWidth + 100;
        mh = outerHeight - innerHeight + 10;

    } else {
        mw = $(document).outerWidth() - $(window).width() + 100;
        mh = $(document).outerHeight() - $(window).height() + 10;
        if (navigator.userAgent.indexOf("MSIE 8") > 0) {
            mh = mh - 20;
        }
        if (navigator.userAgent.indexOf("MSIE 7") > 0) {
            mh = mh - 20;
        }
        window.resizeBy(mw, mh);
    }
};
